#include "sl_lidar_driver.h"
#include <cstdio>
#include <chrono>
#include <memory>
#include <vector>
#include <algorithm>
using C=std::chrono::steady_clock;
int main(){auto c=sl::createSerialPortChannel("/dev/ttyACM0",256000);auto d=sl::createLidarDriver();if(!c||!d)return 1;std::unique_ptr<sl::IChannel> ch(*c);std::unique_ptr<sl::ILidarDriver> l(*d);auto rc=l->connect(ch.get());printf("connect=%08x\n",rc);if(SL_IS_FAIL(rc))return 2;sl::MotorCtrlSupport support{};rc=l->checkMotorCtrlSupport(support,700);printf("motor_support_rc=%08x type=%d\n",rc,int(support));if(SL_IS_FAIL(rc)||support!=sl::MotorCtrlSupportRpm)return 3;struct Stop{sl::ILidarDriver& l;~Stop(){auto s=l.stop();auto z=l.setMotorSpeed(0);printf("stop=%08x zero_speed=%08x\n",s,z);}} stop{*l};printf("default_rc=%08x\n",l->setMotorSpeed());sl::LidarScanMode mode{};rc=l->startScan(false,true,0,&mode);printf("start=%08x mode=%s\n",rc,mode.scan_mode);if(SL_IS_FAIL(rc))return 4;std::vector<sl_lidar_response_measurement_node_hq_t> pts(8192);int fail=0;for(unsigned rpm:{360u,480u}){rc=l->setMotorSpeed(rpm);printf("target_rpm=%u set_rc=%08x\n",rpm,rc);if(SL_IS_FAIL(rc)){++fail;continue;}auto start=C::now(),prev=start;double sum=0;int count=0;while(C::now()-start<std::chrono::seconds(6)){size_t n=pts.size();auto r=l->grabScanDataHq(pts.data(),n,450);auto now=C::now();if(SL_IS_FAIL(r)){printf("grab_error=%08x\n",r);prev=start;continue;}auto ms=std::chrono::duration<double,std::milli>(now-prev).count();auto elapsed=std::chrono::duration<double>(now-start).count();bool use=elapsed>=2.0&&prev!=start&&ms>0;printf("target=%u elapsed=%.3f interval_ms=%.3f points=%zu valid=%zu included=%d\n",rpm,elapsed,ms,n,size_t(std::count_if(pts.begin(),pts.begin()+n,[](auto p){return p.dist_mm_q2!=0;})),use);if(use){sum+=ms;++count;}prev=now;}printf("summary target_rpm=%u intervals=%d frequency_hz=%.3f\n",rpm,count,count?1000*count/sum:0);if(count<2)++fail;}return fail?5:0;}
